CREATE OR REPLACE FUNCTION private.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles WHERE id=_user_id AND status='active') AND CASE WHEN _role='super_admin' THEN EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role='super_admin') ELSE EXISTS(SELECT 1 FROM public.school_memberships WHERE user_id=_user_id AND role=_role AND status='active' AND school_id=private.active_school_id()) END $$;
CREATE OR REPLACE FUNCTION private.is_admin(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT private.has_role(_user_id,'super_admin') OR private.has_role(_user_id,'school_manager') $$;